window.AUTH=window.AUTH||{};window.AUTH["20-1459"]={"d":"20-1459","id":"2021/20-1459","n":"United States v. Taylor","briefs":[{"k":"petitioner","label":"Brief of petitioner United States","date":"2021-09-07","url":"https://www.supremecourt.gov/DocketPDF/20/20-1459/191593/20210907180351638_20-1459tsUnitedStates.pdf","side":"pet","n":92},{"k":"respondent","label":"Brief of respondent Justin Eugene Taylor","date":"2021-10-22","url":"https://www.supremecourt.gov/DocketPDF/20/20-1459/197293/20211022140725084_Taylor%20Respondent%20Brief.pdf","side":"res","n":88},{"k":"reply","label":"Reply of petitioner United States","date":"2021-11-22","url":"https://www.supremecourt.gov/DocketPDF/20/20-1459/201011/20211122165454513_20-1459rbUnitedStates.pdf","side":"pet","n":52}],"opinion":"https://www.supremecourt.gov/opinions/21pdf/596us2r52_886a.pdf","tr":true,"items":[{"t":"case","label":"Bailey v. United States","cite":"516 U.S. 137","y":1995,"id":"1995/94-7448","sc":1,"sum":"The proximity and accessibility test for \"use\" is so broad that no independent role remains for \"carry.\" \"Use\" in Section 924(c)(1) requires more than proximity and accessibility that might embolden a defendant. It requires active employment of the firearm by the defendant, making the firearm an operative factor in relation to the predicate offense.","sumSrc":"Oyez","by":{"0":"21","1":"21","2":"12"}},{"t":"case","label":"Beale v. United States, 10-CR-49","cite":"2013 WL 1209620","y":2013,"court":"E.D.N.C. Jan. 8","by":{"0":"31"}},{"t":"case","label":"Begay v. United States","cite":"553 U.S. 137","y":2008,"id":"2007/06-11543","sc":1,"op":1,"sum":"In a 6-3 vote, the Court held that Begay's DWI convictions did not qualify as \"violent felonies\" because they were too different from the violent felony examples provided by Congress in the Armed Career Criminal Act (such as burglary, arson and extortion). Therefore, Begay should not have been subject to the mandatory sentencing hike.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Borden v. United States","cite":"141 S. Ct. 1817","y":2021,"id":"2020/19-5410","sc":1,"op":6,"ar":1,"sum":"The decision of the Sixth Circuit—holding that an offense with a mental state of recklessness may qualify as a “violent felony” under the Armed Career Criminal Act’s elements clause, 18 U. S. C. §924(e)(2)(B)(i)—is reversed, and the case is remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"14, 21, 27, 28, 32","1":"passim","2":"10, 17"}},{"t":"case","label":"Braxton v. United States","cite":"500 U.S. 344","y":1991,"id":"1990/90-5358","sc":1,"sum":"The court below misapplied the § 1B1.2(a) proviso.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18, 22","2":"3"}},{"t":"case","label":"Brown v. United States","cite":"942 F.3d 1069","y":2019,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/942/1069/","by":{"0":"15"}},{"t":"case","label":"Diaz v. United States","cite":"863 F.3d 781","y":2017,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/863/781/","by":{"0":"15"}},{"t":"case","label":"Elonis v. United States","cite":"575 U.S. 723","y":2015,"id":"2014/13-983","sc":1,"ar":3,"sum":"The Court found that in order to violate the transmission of threats provision, the threat requires both an objective and subjective intent.","sumSrc":"Oyez","by":{"0":"10, 11, 16, 23, 36","1":"25, 26","2":"14, 15, 16"}},{"t":"case","label":"(III) Cases—Continued: Encino Motorcars, LLC v. Navarro","cite":"138 S. Ct. 1134","y":2018,"id":"2017/16-1362","sc":1,"sum":"The Court decided that because service advisors at car dealerships are “salesm[e]n . . . primarily engaged in . . . servicing automobiles,” 29 U.S.C. § 213(b)(10)(A), they are exempt from the Fair Labor Standards Act's overtime-pay requirements.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Gonzales v. Duenas-Alvarez","cite":"549 U.S. 183","y":2007,"id":"2006/05-1629","sc":1,"op":3,"sum":"The Court ruled unanimously that aiding and abetting a theft qualifies as a \"theft offense\" for purposes of the Immigration and Nationality Act. The opinion by Justice Stephen Breyer held that the common law had done away with all distinctions between \"principals\" and \"aiders and abettors\" of theft crimes.","sumSrc":"Oyez","by":{"0":"36, 37","1":"40, 44","2":"6, 7"}},{"t":"case","label":"Hana Fin., Inc. v. Hana Bank","cite":"574 U.S. 418","y":2015,"id":"2014/13-1211","sc":1,"sum":"The Court held that \"trademark tacking\" is a mixed question of fact and law to be decided by the jury.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Hill v. United States","cite":"877 F.3d 717","y":2017,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/877/717/","by":{"0":"20"}},{"t":"case","label":"Hines v. United States","cite":"2021 WL 2291804","y":2021,"court":"D. Md. June 4","by":{"0":"35"}},{"t":"case","label":"Holloway v. United States","cite":"526 U.S. 1","y":1999,"id":"1998/97-7164","sc":1,"sum":"Announced by Justice John Paul Stevens, the Court ruled that the federal carjacking law applies to carjacking crimes committed with \"conditional intent\" of harming drivers who refuse a carjacker's demands. \"The intent requirement...is satisfied when the government proves that at the moment the defendant demanded or took control over the driver's automobile the defendant possessed the intent to seriously harm or kill the driver if necessary to steal the car,\" wrote Justice Stevens.","sumSrc":"Oyez","by":{"0":"35","1":"15, 49"}},{"t":"case","label":"James v. United States","cite":"550 U.S. 192","y":2007,"id":"2006/05-9264","sc":1,"op":2,"sum":"The Court ruled 5-3 that attempted burglary is a \"violent felony\" for purposes of the Armed Career Criminal Act.","sumSrc":"Oyez","by":{"0":"11, 19, 27, 28","2":"10, 17, 19"}},{"t":"case","label":"Johnson v. United States","cite":"559 U.S. 133","y":2010,"id":"2009/08-6925","sc":1,"sum":"The Court held that the Eleventh Circuit Court of Appeals was bound by Florida state law in considering a felony battery charge.","sumSrc":"Oyez","by":{"0":"17, 19, 34","1":"passim"}},{"t":"case","label":"Johnson v. United States","cite":"576 U.S. 591","y":2015,"id":"2014/13-7120","sc":1,"op":7,"sum":"Noting this Court's habit of wielding due process doctrines like vagueness “to achieve its own policy goals”.","sumSrc":"opinion","by":{"0":"7","1":"5, 6, 30"}},{"t":"case","label":"Ladner v. United States","cite":"358 U.S. 169","y":1958,"id":"1958/2","sc":1,"sum":"The single discharge of a shotgun alleged by petitioner in this case would constitute only a single violation of §254; petitioner is entitled to an opportunity to sustain his allegation that his conviction of two assaults rested upon evidence that the wounding of the two officers resulted from the single discharge of the gun; and the judgment is reversed and the cause remanded for further proceedings.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"Leocal v. Ashcroft","cite":"543 U.S. 1","y":2004,"id":"2004/03-583","sc":1,"op":1,"ar":2,"sum":"The Court held that state DUI offenses, except when involving purposeful intent, are accidental and not crimes of violence under federal law. Le therefore did not commit an aggravated felony for which he could be deported.","sumSrc":"Oyez","by":{"0":"11, 14, 19","1":"passim","2":"10"}},{"t":"case","label":"Moncrieffe v. Holder","cite":"569 U.S. 184","y":2013,"id":"2012/11-702","sc":1,"ar":7,"sum":"The Court found that distribution of small amounts of marijuana does not constitute an aggravated felony and thus, does not require deportation of the distributor.","sumSrc":"Oyez","by":{"0":"13, 37","1":"passim","2":"6, 17"}},{"t":"case","label":"Powerex Corp. v. Reliant Energy Servs., Inc.","cite":"551 U.S. 224","y":2007,"id":"2006/05-85","sc":1,"sum":"The Court ruled 7-2 that the Ninth Circuit lacked jurisdiction to review the District Court's remand order. The Court relied on 28 U.S.C. 1447(d), which precludes appellate review of remands based on lack of subject-matter jurisdiction.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Quarles v. United States","cite":"139 S. Ct. 1872","y":2019,"id":"2018/17-778","sc":1,"op":1,"sum":"Michigan’s third-degree home-invasion statute substantially corresponds to or is narrower than generic burglary for purposes of qualifying for enhanced sentencing under the Armed Career Criminal Act.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"39","2":"20"}},{"t":"case","label":"Stokeling v. United States","cite":"139 S. Ct. 544","y":2019,"id":"2018/17-5554","sc":1,"ar":2,"sum":"The Armed Career Criminal Act’s elements clause encompasses a robbery offense that, like Florida’s law, requires the criminal to overcome the victim’s resistance.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"passim","1":"29, 35, 38","2":"5, 6, 13, 18"}},{"t":"case","label":"Swift & Co. v. United States","cite":"196 U.S. 375","y":1905,"id":"1900-1940/196us375","sc":1,"op":1,"sum":"The Court held that congressional power under the Commerce Clause justified regulations of the “beef trust.”","sumSrc":"Oyez","by":{"0":"22","2":"3"}},{"t":"case","label":"Taylor v. United States","cite":"495 U.S. 575","y":1990,"id":"1989/88-7194","sc":1,"op":2,"sum":"An offense constitutes \"burglary\" under §924(e) if, regardless of its exact definition or label, it has the basic elements of a \"generic\" burglary-i. e., an unlawful or unprivileged entry into, or remaining in, a building or other structure, with intent to commit a crime-or if the charging paper and jury instructions actually required the jury to find all the elements of generic burglary in order to convict the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39","1":"48"}},{"t":"case","label":"Taylor v. United States","cite":"136 S. Ct. 2074","y":2016,"id":"2015/14-6166","sc":1,"sum":"The Court determined that, in a prosecution for robbery under the Hobbs Act, the commerce element is satisfied when the government shows that the defendant robbed a drug dealer of drugs or drug proceeds.","sumSrc":"Oyez","by":{"0":"18","1":"11"}},{"t":"case","label":"United States v. Adams","cite":"214 F.3d 724","y":2000,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/214/724/","by":{"0":"31"}},{"t":"case","label":"United States v. Beale","cite":"840 Fed. Appx. 747","y":2021,"court":"4th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./840/747/","by":{"0":"31"}},{"t":"case","label":"United States v. Buck","cite":"847 F.3d 267","y":2017,"url":"https://www.courtlistener.com/c/F.3d/847/267/","by":{"0":"15"}},{"t":"case","label":"United States v. Celaj","cite":"649 F.3d 162","y":2011,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/649/162/","by":{"0":"31"}},{"t":"case","label":"United States v. Clancy","cite":"979 F.3d 1135","y":2020,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/979/1135/","op":1,"by":{"0":"29"}},{"t":"case","label":"United States v. Davis","cite":"139 S. Ct. 2319","y":2019,"id":"2018/18-431","sc":1,"sum":"Title 18 U. S. C. §924(c)(3)(B), which provides enhanced penalties for using a firearm during a “crime of violence,” is unconstitutionally vague.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"6, 7, 8","1":"passim","2":"16"}},{"t":"case","label":"United States v. Dominguez","cite":"954 F.3d 1251","y":2020,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/954/1251/","by":{"0":"9, 15, 31","2":"3"}},{"t":"case","label":"United States v. England","cite":"507 F.3d 581","y":2007,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/507/581/","by":{"0":"24","1":"26"}},{"t":"case","label":"United States v. García-Ortiz","cite":"904 F.3d 102","y":2018,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/904/102/","by":{"0":"15","2":"3"}},{"t":"case","label":"United States v. Ingram","cite":"947 F.3d 1021","y":2020,"url":"https://www.courtlistener.com/c/F.3d/947/1021/","by":{"0":"9"}},{"t":"case","label":"United States v. Johnson","cite":"645 Fed. Appx. 954","y":2016,"url":"https://www.courtlistener.com/c/Fed.%20Appx./645/954/","by":{"0":"31"}},{"t":"case","label":"United States v. Knife","cite":"592 F.2d 472","y":1979,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/592/472/","by":{"0":"26"}},{"t":"case","label":"United States v. Kosma","cite":"951 F.2d 549","y":1991,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/951/549/","sum":"Explaining that it is “not necessary that [the] President ‘be harmed or made aware of [a] threat’ ” under 18 U.S.C. 871 (1988).","sumSrc":"brief:0","by":{"0":"24","1":"27"}},{"t":"case","label":"United States v. LiCausi","cite":"167 F.3d 36","y":1999,"url":"https://www.courtlistener.com/c/F.3d/167/36/","by":{"0":"31"}},{"t":"case","label":"United States v. Maddox","cite":"803 F.3d 1215","y":2015,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/803/1215/","by":{"0":"29"}},{"t":"case","label":"United States v. Martin","cite":"163 F.3d 1212","y":1998,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/163/1212/","by":{"0":"24","1":"27"}},{"t":"case","label":"United States v. Mathis","cite":"932 F.3d 242","y":2019,"url":"https://www.courtlistener.com/c/F.3d/932/242/","by":{"0":"8, 15"}},{"t":"case","label":"United States v. McCoy","cite":"995 F.3d 32","y":2021,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/995/32/","by":{"0":"35","2":"7"}},{"t":"case","label":"United States v. Melgar-Cabrera","cite":"892 F.3d 1053","y":2018,"url":"https://www.courtlistener.com/c/F.3d/892/1053/","by":{"0":"15, 33"}},{"t":"case","label":"United States v. Parkes","cite":"497 F.3d 220","y":2007,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/497/220/","by":{"0":"29"}},{"t":"case","label":"United States v. Reed","cite":"756 F.3d 184","y":2014,"url":"https://www.courtlistener.com/c/F.3d/756/184/","by":{"0":"29"}},{"t":"case","label":"United States v. Reid","cite":"517 F.2d 953","y":1975,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/517/953/","by":{"0":"24"}},{"t":"case","label":"United States v. Resendiz-Ponce","cite":"549 U.S. 102","y":2007,"id":"2006/05-998","sc":1,"op":4,"sum":"The Court ruled that Resendiz-Ponce's indictment was not defective at all, and thus it did not reach the question of whether a failure to state each element of the charged crime can ever be harmless error. Justice John Paul Stevens wrote the opinion for the 8-1 majority.","sumSrc":"Oyez","by":{"0":"18, 22","1":"11, 23","2":"2, 3, 4"}},{"t":"case","label":"United States v. Richardson","cite":"948 F.3d 733","y":2020,"url":"https://www.courtlistener.com/c/F.3d/948/733/","by":{"0":"15"}},{"t":"case","label":"United States v. Rivera","cite":"847 F.3d 847","y":2017,"url":"https://www.courtlistener.com/c/F.3d/847/847/","by":{"0":"15"}},{"t":"case","label":"United States v. Rodriguez-Moreno","cite":"526 U.S. 275","y":1999,"id":"1998/97-1139","sc":1,"sum":"The Court held that \"[v]enue in a prosecution for using or carrying a firearm 'during and in relation to any crime of violence' in violation of section 924(c)(1) is proper in any district where the crime of violence was committed.\" Justice Thomas wrote for the Court that, \"A kidnapping...does not end until the victim is free.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"United States v. Rose","cite":"832 Fed. Appx. 814","y":2021,"court":"4th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./832/814/","by":{"0":"28"}},{"t":"case","label":"United States v. Sherrill","cite":"972 F.3d 752","y":2020,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/972/752/","by":{"0":"29"}},{"t":"case","label":"United States v. Simms","cite":"914 F.3d 229","y":2019,"url":"https://www.courtlistener.com/c/F.3d/914/229/","ar":1,"by":{"0":"7, 8","1":"3"}},{"t":"case","label":"United States v. Smith","cite":"928 F.2d 407","y":1991,"url":"https://www.courtlistener.com/c/F.2d/928/407/","sum":"Explaining that targeted judge’s awareness of a threat is not relevant under 18 U.S.C. 115(a)(1)(B).","sumSrc":"brief:0","by":{"0":"24"}},{"t":"case","label":"United States v. Spring","cite":"305 F.3d 276","y":2002,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/305/276/","by":{"0":"24","1":"26"}},{"t":"case","label":"United States v. St. Hubert","cite":"909 F.3d 335","y":2018,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/909/335/","op":2,"by":{"0":"9","2":"3"}},{"t":"case","label":"United States v. Thornton","cite":"539 F.3d 741","y":2008,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/539/741/","op":1,"by":{"0":"35"}},{"t":"case","label":"United States v. Thrower","cite":"914 F.3d 770","y":2019,"url":"https://www.courtlistener.com/c/F.3d/914/770/","by":{"0":"36"}},{"t":"case","label":"United States v. Walker","cite":"657 F.3d 160","y":2011,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/657/160/","by":{"0":"29"}},{"t":"case","label":"United States v. Walker","cite":"990 F.3d 316","y":2021,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/990/316/","sum":"Explaining that “read[ing] the words ‘attempted use’ in the elements clause of § 924(c) to capture attempt offenses” is consistent with Congress’s general practice of “interweav[ing] prohibitions on attempted crimes within the statutes defining the underlying substantive offenses”.","sumSrc":"brief:0","by":{"0":"20, 32, 39","1":"28","2":"10, 21"}},{"t":"case","label":"United States v. Washington","cite":"869 F.3d 193","y":2017,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/869/193/","by":{"0":"23, 30"}},{"t":"case","label":"United States v. Wrobel","cite":"841 F.3d 450","y":2016,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/841/450/","by":{"0":"39"}},{"t":"case","label":"Virginia v. Black","cite":"538 U.S. 343","y":2003,"id":"2002/01-1107","sc":1,"op":2,"sum":"The Court held that a law banning cross-burning with the intent to intimidate is constitutional. However, cross burning is not prima facie evidence of intent to intimidate.","sumSrc":"Oyez","by":{"0":"16, 23","1":"15, 17","2":"14"}},{"t":"case","label":"Voisine v. United States","cite":"136 S. Ct. 2272","y":2016,"id":"2015/14-10154","sc":1,"ar":1,"sum":"The Court held that a reckless domestic violence assault qualifies as misdemeanor crime of domestic violence for the purpose of prohibiting firearm possession.","sumSrc":"Oyez","by":{"0":"20, 21","1":"13, 14","2":"12"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(e)","(e)(2)(B)(i)","(e)(2)(B)(ii)","(c)(2000)","(c)","(c)(1)(A)","(c)(3)","(c)(3)(A)","(c)(3)(B)"],"stext":{"head":"§924. Penalties","paras":[[0,"(a)(1) Except as otherwise provided in this subsection, subsection (b), (c), (f), or (p) of this section, or in section 929, whoever—"],[1,"(A) knowingly makes any false statement or representation with respect to the information required by this chapter to be kept in the records of a person licensed under this chapter or in applying for any license or exemption or relief from disability under the provisions of this chapter;"],[1,"(B) knowingly violates subsection (a)(4), (f), (k), or (q) of section 922;"],[1,"(C) knowingly imports or brings into the United States or any possession thereof any firearm or ammunition in violation of section 922(l); or"],[1,"(D) willfully violates any other provision of this chapter,"],[0,"shall be fined under this title, imprisoned not more than five years, or both."],[0,"(2) Whoever knowingly violates subsection (a)(6), (h), (i), (j), or (o) of section 922 shall be fined as provided in this title, imprisoned not more than 10 years, or both."],[0,"(3) Any licensed dealer, licensed importer, licensed manufacturer, or licensed collector who knowingly—"],[1,"(A) makes any false statement or representation with respect to the information required by the provisions of this chapter to be kept in the records of a person licensed under this chapter, or"],[1,"(B) violates subsection (m) of section 922,"],[0,"shall be fined under this title, imprisoned not more than one year, or both."],[0,"(4) Whoever violates section 922(q) shall be fined under this title, imprisoned for not more than 5 years, or both. Notwithstanding any other provision of law, the term of imprisonment imposed under this paragraph shall not run concurrently with any other term of imprisonment imposed under any other provision of law. Except for the authorization of a term of imprisonment of not more than 5 years made in this paragraph, for the purpose of any other law a violation of section 922(q) shall be deemed to be a misdemeanor."],[0,"(5) Whoever knowingly violates subsection (s) or (t) of section 922 shall be fined under this title, imprisoned for not more than 1 year, or both."],[0,"(6)(A)(i) A juvenile who violates section 922(x) shall be fined under this title, imprisoned not more than 1 year, or both, except that a juvenile described in clause (ii) shall be sentenced to probation on appropriate conditions and shall not be incarcerated unless the juvenile fails to comply with a condition of probation."],[0,"(ii) A juvenile is described in this clause if—"],[1,"(I) the offense of which the juvenile is charged is possession of a handgun or ammunition in violation of section 922(x)(2); and"],[1,"(II) the juvenile has not been convicted in any court of an offense (including an offense under section 922(x) or a similar State law, but not including any other offense consisting of conduct that if engaged in by an adult would not constitute an offense) or adjudicated as a juvenile delinquent for conduct that if engaged in by an adult would constitute an offense."],[0,"(B) A person other than a juvenile who knowingly violates section 922(x)—"],[1,"(i) shall be fined under this title, imprisoned not more than 1 year, or both; and"],[1,"(ii) if the person sold, delivered, or otherwise transferred a handgun or ammunition to a juvenile knowing or having reasonable cause to know that the juvenile intended to carry or otherwise possess or discharge or otherwise use the handgun or ammunition in the commission of a crime of violence, shall be fined under this title, imprisoned not more than 10 years, or both."],[0,"(7) Whoever knowingly violates section 931 shall be fined under this title, imprisoned not more than 3 years, or both."],[0,"(8) Whoever knowingly violates subsection (d) or (g) of section 922 shall be fined under this title, imprisoned for not more than 15 years, or both."],[0,"(b) Whoever, with intent to commit therewith an offense punishable by imprisonment for a term exceeding one year, or with knowledge or reasonable cause to believe that an offense punishable by imprisonment for a term exceeding one year is to be committed therewith, ships, transports, or receives a firearm or any ammunition in interstate or foreign commerce shall be fined under this title, or imprisoned not more than ten years, or both."],[0,"(c)(1)(A) Except to the extent that a greater minimum sentence is otherwise provided by this subsection or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries a firearm, or who, in furtherance of any such crime, possesses a firearm, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime—"],[1,"(i) be sentenced to a term of imprisonment of not less than 5 years;"],[1,"(ii) if the firearm is brandished, be sentenced to a term of imprisonment of not less than 7 years; and"],[1,"(iii) if the firearm is discharged, be sentenced to a term of imprisonment of not less than 10 years."],[0,"(B) If the firearm possessed by a person convicted of a violation of this subsection—"],[1,"(i) is a short-barreled rifle, short-barreled shotgun, or semiautomatic assault weapon, the person shall be sentenced to a term of imprisonment of not less than 10 years; or"],[1,"(ii) is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, the person shall be sentenced to a term of imprisonment of not less than 30 years."],[0,"(C) In the case of a violation of this subsection that occurs after a prior conviction under this subsection has become final, the person shall—"],[1,"(i) be sentenced to a term of imprisonment of not less than 25 years; and"],[1,"(ii) if the firearm involved is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, be sentenced to imprisonment for life."],[0,"(D) Notwithstanding any other provision of law—"],[1,"(i) a court shall not place on probation any person convicted of a violation of this subsection; and"],[1,"(ii) no term of imprisonment imposed on a person under this subsection shall run concurrently with any other term of imprisonment imposed on the person, including any term of imprisonment imposed for the crime of violence or drug trafficking crime during which the firearm was used, carried, or possessed."],[0,"(2) For purposes of this subsection, the term \"drug trafficking crime\" means any felony punishable under the Controlled Substances Act (21 U.S.C. 801 et seq.), the Controlled Substances Import and Export Act (21 U.S.C. 951 et seq.), or chapter 705 of title 46."],[0,"(3) For purposes of this subsection the term \"crime of violence\" means an offense that is a felony and—"],[1,"(A) has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(B) that by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."],[0,"(4) For purposes of this subsection, the term \"brandish\" means, with respect to a firearm, to display all or part of the firearm, or otherwise make the presence of the firearm known to another person, in order to intimidate that person, regardless of whether the firearm is directly visible to that person."],[0,"(5) Except to the extent that a greater minimum sentence is otherwise provided under this subsection, or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries armor piercing ammunition, or who, in furtherance of any such crime, possesses armor piercing ammunition, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime or conviction under this section—"],[1,"(A) be sentenced to a term of imprisonment of not less than 15 years; and"],[1,"(B) if death results from the use of such ammunition—"],[2,"(i) if the killing is murder (as defined in section 1111), be punished by death or sentenced to a term of imprisonment for any term of years or for life; and"],[2,"(ii) if the killing is manslaughter (as defined in section 1112), be punished as provided in section 1112."],[0,"(d)(1) Any firearm or ammunition involved in or used in any knowing violation of subsection (a)(4), (a)(6), (f), (g), (h), (i), (j), or (k) of section 922, or knowing importation or bringing into the United States or any possession thereof any firearm or ammunition in violation of section 922(l), or knowing violation of section 924, 932, or 933, or willful violation of any other provision of this chapter or any rule or regulation promulgated thereunder, or any violation of any other criminal law of the United States, or any firearm or ammunition intended to be used in any offense referred to in paragraph (3) of this subsection, where such intent is demonstrated by clear and convincing evidence, shall be subject to seizure and forfeiture, and all provisions of the Internal Revenue Code of 1986 relating to the seizure, forfeiture, and disposition of firearms, as defined in section 5845(a) of that Code, shall, so far as applicable, extend to seizures and forfeitures under the provisions of this chapter: Provided, That upon acquittal of the owner or possessor, or dismissal of the charges against him other than upon motion of the Government prior to trial, or lapse of or court termination of the restraining order to which he is subject, the seized or relinquished firearms or ammunition shall be returned forthwith to the owner or possessor or to a person delegated by the owner or possessor unless the return of the firearms or ammunition would place the owner or possessor or his delegate in violation of law. Any action or proceeding for the forfeiture of firearms or ammunition shall be commenced within one hundred and twenty days of such seizure."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/924?type=usc&year=mostrecent&link-type=html"},"op":6,"ar":1,"head":"§924. Penalties","tname":"Crimes and Criminal Procedure","by":{"0":"17, 17, 7, passim, 28, 31, 37, 38, 6, passim, passim, 7, 8, 27","1":"passim, 3, 5, 20","2":"20, 21, 1, 9, 20, 21, passim, 17"}},{"t":"law","label":"Firearms Owners’ Protection Act, Pub. L. No. 99-308","url":"https://www.govinfo.gov/link/statute/100/456","by":{"0":"17"}},{"t":"usc","label":"18 U.S.C. § 1951","url":"https://www.law.cornell.edu/uscode/text/18/1951","subs":["(a)","(b)(1)","(b)(2)"],"stext":{"head":"§1951. Interference with commerce by threats or violence","paras":[[0,"(a) Whoever in any way or degree obstructs, delays, or affects commerce or the movement of any article or commodity in commerce, by robbery or extortion or attempts or conspires so to do, or commits or threatens physical violence to any person or property in furtherance of a plan or purpose to do anything in violation of this section shall be fined under this title or imprisoned not more than twenty years, or both."],[0,"(b) As used in this section—"],[1,"(1) The term \"robbery\" means the unlawful taking or obtaining of personal property from the person or in the presence of another, against his will, by means of actual or threatened force, or violence, or fear of injury, immediate or future, to his person or property, or property in his custody or possession, or the person or property of a relative or member of his family or of anyone in his company at the time of the taking or obtaining."],[1,"(2) The term \"extortion\" means the obtaining of property from another, with his consent, induced by wrongful use of actual or threatened force, violence, or fear, or under color of official right."],[1,"(3) The term \"commerce\" means commerce within the District of Columbia, or any Territory or Possession of the United States; all commerce between any point in a State, Territory, Possession, or the District of Columbia and any point outside thereof; all commerce between points within the same State through any place outside such State; and all other commerce over which the United States has jurisdiction."],[0,"(c) This section shall not be construed to repeal, modify or affect section 17 of Title 15, sections 52, 101–115, 151–166 of Title 29 or sections 151–188 of Title 45."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1951?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1951. Interference with commerce by threats or violence","tname":"Crimes and Criminal Procedure","by":{"0":"3, 5, 11, 22, 38, 14, 18, 34, 10, 12, 15, 16, 33, 34","1":"11, 11, 16, 24","2":"2, 9, 10, 2, 9, 10, 5, 15, 8"}},{"t":"usc","label":"18 U.S.C. § 2","url":"https://www.law.cornell.edu/uscode/text/18/2","by":{"0":"5"}},{"t":"usc","label":"18 U.S.C. § 16","url":"https://www.law.cornell.edu/uscode/text/18/16","subs":["(a)"],"stext":{"head":"§16. Crime of violence defined","paras":[[0,"The term \"crime of violence\" means—"],[1,"(a) an offense that has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(b) any other offense that is a felony and that, by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/16?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§16. Crime of violence defined","tname":"Crimes and Criminal Procedure","by":{"0":"17","1":"passim","2":"21"}},{"t":"usc","label":"18 U.S.C. § 113","url":"https://www.law.cornell.edu/uscode/text/18/113","subs":["(d)(1982)","(e)(1982)","(a)"],"stext":{"head":"§113. Assaults within maritime and territorial jurisdiction","paras":[[0,"(a) Whoever, within the special maritime and territorial jurisdiction of the United States, is guilty of an assault shall be punished as follows:"],[1,"(1) Assault with intent to commit murder or a violation of section 2241 or 2242, by a fine under this title, imprisonment for not more than 20 years, or both."],[1,"(2) Assault with intent to commit any felony, except murder or a violation of section 2241 or 2242, by a fine under this title or imprisonment for not more than ten years, or both."],[1,"(3) Assault with a dangerous weapon, with intent to do bodily harm, by a fine under this title or imprisonment for not more than ten years, or both."],[1,"(4) Assault by striking, beating, or wounding, by a fine under this title or imprisonment for not more than 1 year, or both."],[1,"(5) Simple assault, by a fine under this title or imprisonment for not more than six months, or both, or if the victim of the assault is an individual who has not attained the age of 16 years, by fine under this title or imprisonment for not more than 1 year, or both."],[1,"(6) Assault resulting in serious bodily injury, by a fine under this title or imprisonment for not more than ten years, or both."],[1,"(7) Assault resulting in substantial bodily injury to a spouse or intimate partner, a dating partner, or an individual who has not attained the age of 16 years, by a fine under this title or imprisonment for not more than 5 years, or both."],[1,"(8) Assault of a spouse, intimate partner, or dating partner by strangling, suffocating, or attempting to strangle or suffocate, by a fine under this title, imprisonment for not more than 10 years, or both."],[0,"(b) Definitions.—In this section—"],[1,"(1) the term \"substantial bodily injury\" means bodily injury which involves—"],[2,"(A) a temporary but substantial disfigurement; or"],[2,"(B) a temporary but substantial loss or impairment of the function of any bodily member, organ, or mental faculty;"],[1,"(2) the term \"serious bodily injury\" has the meaning given that term in section 1365 of this title;"],[1,"(3) the terms \"dating partner\" and \"spouse or intimate partner\" have the meanings 1 given those terms in section 2266;"],[1,"(4) the term \"strangling\" means intentionally, knowingly, or recklessly impeding the normal breathing or circulation of the blood of a person by applying pressure to the throat or neck, regardless of whether that conduct results in any visible injury or whether there is any intent to kill or protractedly injure the victim; and"],[1,"(5) the term \"suffocating\" means intentionally, knowingly, or recklessly impeding the normal breathing of a person by covering the mouth of the person, the nose of the person, or both, regardless of whether that conduct results in any visible injury or whether there is any intent to kill or protractedly injure the victim."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/113?type=usc&year=mostrecent&link-type=html"},"head":"§113. Assaults within maritime and territorial jurisdiction","tname":"Crimes and Criminal Procedure","by":{"0":"25, 25","1":"37, 37, 37"}},{"t":"usc","label":"18 U.S.C. § 115","url":"https://www.law.cornell.edu/uscode/text/18/115","subs":["(a)(1)(B)"],"by":{"0":"25"}},{"t":"usc","label":"18 U.S.C. § 871","url":"https://www.law.cornell.edu/uscode/text/18/871","subs":["(1988)"],"by":{"0":"25"}},{"t":"usc","label":"18 U.S.C. § 2111","url":"https://www.law.cornell.edu/uscode/text/18/2111","by":{"0":"38"}},{"t":"usc","label":"18 U.S.C. § 2113","url":"https://www.law.cornell.edu/uscode/text/18/2113","subs":["(a)"],"stext":{"head":"§2113. Bank robbery and incidental crimes","paras":[[0,"(a) Whoever, by force and violence, or by intimidation, takes, or attempts to take, from the person or presence of another, or obtains or attempts to obtain by extortion any property or money or any other thing of value belonging to, or in the care, custody, control, management, or possession of, any bank, credit union, or any savings and loan association; or"],[0,"Whoever enters or attempts to enter any bank, credit union, or any savings and loan association, or any building used in whole or in part as a bank, credit union, or as a savings and loan association, with intent to commit in such bank, credit union, or in such savings and loan association, or building, or part thereof, so used, any felony affecting such bank, credit union, or such savings and loan association and in violation of any statute of the United States, or any larceny—"],[0,"Shall be fined under this title or imprisoned not more than twenty years, or both."],[0,"(b) Whoever takes and carries away, with intent to steal or purloin, any property or money or any other thing of value exceeding $1,000 belonging to, or in the care, custody, control, management, or possession of any bank, credit union, or any savings and loan association, shall be fined under this title or imprisoned not more than ten years, or both; or"],[0,"Whoever takes and carries away, with intent to steal or purloin, any property or money or any other thing of value not exceeding $1,000 belonging to, or in the care, custody, control, management, or possession of any bank, credit union, or any savings and loan association, shall be fined under this title or imprisoned not more than one year, or both."],[0,"(c) Whoever receives, possesses, conceals, stores, barters, sells, or disposes of, any property or money or other thing of value which has been taken or stolen from a bank, credit union, or savings and loan association in violation of subsection (b), knowing the same to be property which has been stolen shall be subject to the punishment provided in subsection (b) for the taker."],[0,"(d) Whoever, in committing, or in attempting to commit, any offense defined in subsections (a) and (b) of this section, assaults any person, or puts in jeopardy the life of any person by the use of a dangerous weapon or device, shall be fined under this title or imprisoned not more than twenty-five years, or both."],[0,"(e) Whoever, in committing any offense defined in this section, or in avoiding or attempting to avoid apprehension for the commission of such offense, or in freeing himself or attempting to free himself from arrest or confinement for such offense, kills any person, or forces any person to accompany him without the consent of such person, shall be imprisoned not less than ten years, or if death results shall be punished by death or life imprisonment."],[0,"(f) As used in this section the term \"bank\" means any member bank of the Federal Reserve System, and any bank, banking association, trust company, savings bank, or other banking institution organized or operating under the laws of the United States, including a branch or agency of a foreign bank (as such terms are defined in paragraphs (1) and (3) of section 1(b) of the International Banking Act of 1978), and any institution the deposits of which are insured by the Federal Deposit Insurance Corporation."],[0,"(g) As used in this section the term \"credit union\" means any Federal credit union and any State-chartered credit union the accounts of which are insured by the National Credit Union Administration Board, and any \"Federal credit union\" as defined in section 2 of the Federal Credit Union Act. The term \"State-chartered credit union\" includes a credit union chartered under the laws of a State of the United States, the District of Columbia, or any commonwealth, territory, or possession of the United States."],[0,"(h) As used in this section, the term \"savings and loan association\" means—"],[1,"(1) a Federal savings association or State savings association (as defined in section 3(b) of the Federal Deposit Insurance Act (12 U.S.C. 1813(b))) having accounts insured by the Federal Deposit Insurance Corporation; and"],[1,"(2) a corporation described in section 3(b)(1)(C) of the Federal Deposit Insurance Act (12 U.S.C. 1813(b)(1)(C)) that is operating under the laws of the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2113?type=usc&year=mostrecent&link-type=html"},"head":"§2113. Bank robbery and incidental crimes","tname":"Crimes and Criminal Procedure","by":{"0":"38","1":"45"}},{"t":"usc","label":"18 U.S.C. § 2118","url":"https://www.law.cornell.edu/uscode/text/18/2118","by":{"0":"38"}},{"t":"usc","label":"18 U.S.C. § 2119","url":"https://www.law.cornell.edu/uscode/text/18/2119","by":{"0":"34, 38"}},{"t":"usc","label":"21 U.S.C. § 846","url":"https://www.law.cornell.edu/uscode/text/21/846","by":{"0":"5"}},{"t":"usc","label":"28 U.S.C. § 2255","url":"https://www.law.cornell.edu/uscode/text/28/2255","subs":["(h)"],"stext":{"head":"§2255. Federal custody; remedies on motion attacking sentence","paras":[[0,"(a) A prisoner in custody under sentence of a court established by Act of Congress claiming the right to be released upon the ground that the sentence was imposed in violation of the Constitution or laws of the United States, or that the court was without jurisdiction to impose such sentence, or that the sentence was in excess of the maximum authorized by law, or is otherwise subject to collateral attack, may move the court which imposed the sentence to vacate, set aside or correct the sentence."],[0,"(b) Unless the motion and the files and records of the case conclusively show that the prisoner is entitled to no relief, the court shall cause notice thereof to be served upon the United States attorney, grant a prompt hearing thereon, determine the issues and make findings of fact and conclusions of law with respect thereto. If the court finds that the judgment was rendered without jurisdiction, or that the sentence imposed was not authorized by law or otherwise open to collateral attack, or that there has been such a denial or infringement of the constitutional rights of the prisoner as to render the judgment vulnerable to collateral attack, the court shall vacate and set the judgment aside and shall discharge the prisoner or resentence him or grant a new trial or correct the sentence as may appear appropriate."],[0,"(c) A court may entertain and determine such motion without requiring the production of the prisoner at the hearing."],[0,"(d) An appeal may be taken to the court of appeals from the order entered on the motion as from a final judgment on application for a writ of habeas corpus."],[0,"(e) An application for a writ of habeas corpus in behalf of a prisoner who is authorized to apply for relief by motion pursuant to this section, shall not be entertained if it appears that the applicant has failed to apply for relief, by motion, to the court which sentenced him, or that such court has denied him relief, unless it also appears that the remedy by motion is inadequate or ineffective to test the legality of his detention."],[0,"(f) A 1-year period of limitation shall apply to a motion under this section. The limitation period shall run from the latest of—"],[1,"(1) the date on which the judgment of conviction becomes final;"],[1,"(2) the date on which the impediment to making a motion created by governmental action in violation of the Constitution or laws of the United States is removed, if the movant was prevented from making a motion by such governmental action;"],[1,"(3) the date on which the right asserted was initially recognized by the Supreme Court, if that right has been newly recognized by the Supreme Court and made retroactively applicable to cases on collateral review; or"],[1,"(4) the date on which the facts supporting the claim or claims presented could have been discovered through the exercise of due diligence."],[0,"(g) Except as provided in section 408 of the Controlled Substances Act, in all proceedings brought under this section, and any subsequent proceedings on review, the court may appoint counsel, except as provided by a rule promulgated by the Supreme Court pursuant to statutory authority. Appointment of counsel under this section shall be governed by section 3006A of title 18."],[0,"(h) A second or successive motion must be certified as provided in section 2244 by a panel of the appropriate court of appeals to contain—"],[1,"(1) newly discovered evidence that, if proven and viewed in light of the evidence as a whole, would be sufficient to establish by clear and convincing evidence that no reasonable factfinder would have found the movant guilty of the offense; or"],[1,"(2) a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2255?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§2255. Federal custody; remedies on motion attacking sentence","tname":"Judiciary and Judicial Procedure","by":{"0":"4, 6, 7, 8, 6"}},{"t":"case","label":"Alexis v. Barr","cite":"960 F.3d 722","y":2020,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/960/722/","by":{"1":"44"}},{"t":"case","label":"Azar v. Allina Health Servs.","cite":"139 S. Ct. 1804","y":2019,"id":"2018/17-1484","sc":1,"sum":"Because the Department of Health and Human Services neglected its statutory notice-and-comment obligations when it revealed a new policy that dramatically—and retroactively—reduced Medicare payments to hospitals serving low-income patients, its policy must be vacated.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"33"}},{"t":"case","label":"Chapman v. United States","cite":"500 U.S. 453","y":1991,"id":"1990/90-5744","sc":1,"sum":"A pure dose of the hallucinogenic drug LSD is so small that it must be sold to retail customers in a \"carrier\" created by dissolving pure LSD and, inter alia, spraying the resulting solution on paper. That paper is then cut into \"one-dose\" squares, which users swallow, lick, or drop into a beverage to release the drug. Petitioners were convicted in the District Court of selling 10 sheets (1,000 doses) of blotter …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"48"}},{"t":"case","label":"Chrzanoski v. Ashcroft","cite":"327 F.3d 188","y":2003,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/327/188/","sum":"Rejecting the government’s 39 “attempts to avoid the clear language of § 16(a)” by relying on the report’s reference to simple assault.","sumSrc":"brief:1","by":{"1":"38"}},{"t":"case","label":"Crandon v. United States","cite":"494 U.S. 152","y":1990,"id":"1989/88-931","sc":1,"sum":"Section 209(a) does not apply to a severance payment that is made to encourage the payee to accept Government employment, but is made before the payee becomes a Government employee.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"34","2":"20"}},{"t":"case","label":"Descamps v. United States","cite":"570 U.S. 254","y":2013,"id":"2012/11-9540","sc":1,"op":4,"sum":"The Court held that it was improper to apply the categorical approach in which the courts apply elements of a prior conviction with elements of a generic crime in order to enhance a sentence under the ACCA.","sumSrc":"Oyez","by":{"1":"42"}},{"t":"case","label":"Esquivel-Quintana v. Sessions","cite":"137 S. Ct. 1562","y":2017,"id":"2016/16-54","sc":1,"sum":"The Court determined that the crime of “unlawful sexual intercourse with a minor” as defined by California law cannot be categorically considered the aggravated felony of “sexual abuse of a minor” for the purpose of mandatory removal under the Immigration and Nationality Act (INA).","sumSrc":"Oyez","by":{"1":"42"}},{"t":"case","label":"Fernandez-Ruiz v. Gonzales","cite":"466 F.3d 1121","y":2006,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/466/1121/","by":{"1":"38"}},{"t":"case","label":"Gonzalez v. Wilkinson","cite":"990 F.3d 654","y":2021,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/990/654/","by":{"1":"43, 44"}},{"t":"case","label":"Gordon v. Barr","cite":"965 F.3d 252","y":2020,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/965/252/","by":{"1":"40"}},{"t":"case","label":"Huddleston v. United States","cite":"415 U.S. 814","y":1974,"id":"1973/72-1076","sc":1,"sum":"Section 922 (a) (6) applies to the redemption of a firearm from a pawnshop.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"48","2":"19"}},{"t":"case","label":"Hughey v. United States","cite":"495 U.S. 411","y":1990,"id":"1989/89-5691","sc":1,"sum":"A VWPA restitution award is authorized only for the loss caused by the specific conduct that is the basis of the offense of conviction.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"33"}},{"t":"case","label":"Hylton v. Sessions","cite":"897 F.3d 57","y":2018,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/897/57/","by":{"1":"43, 44"}},{"t":"case","label":"Jarecki v. G. D. Searle & Co.","cite":"367 U.S. 303","y":1961,"id":"1960/151","sc":1,"sum":"1. Development of new products is not \"discovery\" within the meaning of § 456 (a) (2) (B) of the Internal Revenue Code of 1939, as amended; and income resulting from the manufacture and sale of certain patented drugs, cameras, camera equipment and stereo products resulting from inventions is not included within the statutory definition of \"abnormal income,\" in § 456 (a), so as to qualify for Korean War excess …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23"}},{"t":"case","label":"Jean-Louis v. Att’y Gen.","cite":"582 F.3d 462","y":2009,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/582/462/","by":{"1":"43"}},{"t":"case","label":"Jones v. United States","cite":"529 U.S. 848","y":2000,"id":"1999/99-5739","sc":1,"sum":"Delivered by Justice Ruth Bader Ginsburg, the Court held that an owner-occupied residence not used for any commercial purpose does not qualify as property \"used in\" commerce or commerce-affecting activity, such that arson of such a dwelling is not subject to federal prosecution under section 844(i).","sumSrc":"Oyez","by":{"1":"48"}},{"t":"case","label":"Liparota v. United States","cite":"471 U.S. 419","y":1985,"id":"1984/84-5108","sc":1,"sum":"Absent any indication of a contrary purpose in the statute's language or legislative history, the Government in a prosecution for violation of § 2024(b)(1) must prove that the defendant knew that his acquisition or possession of food stamps was in a manner unauthorized by statute or regulations.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"48"}},{"t":"case","label":"Lopez-Aguilar v. Barr","cite":"948 F.3d 1143","y":2020,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/948/1143/","by":{"1":"43"}},{"t":"case","label":"Mathis v. United States","cite":"136 S. Ct. 2243","y":2016,"id":"2015/15-6092","sc":1,"sum":"The Court determined that a state crime cannot qualify as a predicate offense under the Armed Career Criminal Act (ACCA) if the elements of the state offense are broader than those of a listed generic offense based on an “elements-only inquiry,” not a modified categorical approach.","sumSrc":"Oyez","by":{"1":"3, 42, 44"}},{"t":"case","label":"Mellouli v. Lynch","cite":"135 S. Ct. 1980","y":2015,"id":"2014/13-1034","sc":1,"sum":"The Government must prove the connection between a state drug paraphernalia conviction and a substance listed in the Controlled Substances Act to trigger deportability under the Immigration and Nationality Act.","sumSrc":"Oyez","by":{"1":"42, 43"}},{"t":"case","label":"Pereida v. Wilkinson","cite":"141 S. Ct. 754","y":2021,"id":"2020/19-438","sc":1,"sum":"A nonpermanent resident seeking to cancel a lawful removal order fails to carry his burden of showing that he has not been convicted of a disqualifying offense when the statutory conviction on his record is ambiguous regarding whether a disqualifying offense formed the basis of his conviction.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"4, 18, 31, 46"}},{"t":"case","label":"Popal v. Gonzalez","cite":"416 F.3d 249","y":2005,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/416/249/","sum":"Rejecting government’s reliance on the report’s reference to simple assault to argue that Section 16(a)’s crime-ofviolence definition encompasses simple assault committed recklessly.","sumSrc":"brief:1","by":{"1":"38"}},{"t":"case","label":"Ramos v. United States AG","cite":"709 F.3d 1066","y":2013,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/709/1066/","by":{"1":"43"}},{"t":"case","label":"Republic of Sudan v. Harrison","cite":"139 S. Ct. 1048","y":2019,"id":"2018/16-1094","sc":1,"sum":"When civil process is served on a foreign state under the Foreign Sovereign Immunities Act of 1976, 28 U. S. C. §1608(a)(3) requires a mailing to be sent directly to the foreign minister’s office in the foreign state.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"16"}},{"t":"case","label":"Sessions v. Dimaya","cite":"138 S. Ct. 1204","y":2018,"id":"2017/15-1498","sc":1,"sum":"A case in which the Court struck down the Immigration and Nationality Act’s “crime of violence” provision as unconstitutionally vague in violation of the Due Process Clause of the Fifth Amendment.","sumSrc":"Oyez","by":{"1":"30","2":"17"}},{"t":"case","label":"Shular v. United States","cite":"140 S. Ct. 779","y":2020,"id":"2019/18-6662","sc":1,"sum":"The Court held that the Armed Career Criminal Act’s “serious drug offense” definition requires only that a state offense involve the conduct specified in the statute; it does not require that the state offense match certain generic offenses.","sumSrc":"Oyez","by":{"1":"47, 48","2":"19"}},{"t":"case","label":"Sturgeon v. Frost","cite":"577 U.S. 424","y":2016,"id":"2015/14-1209","sc":1,"sum":"The Court held that the Alaska National Interest Lands Conservation Act of 1980 did not allow the National Park Service to regulate all land physically within the boundaries of the National Park System in Alaska.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Swaby v. Yates","cite":"847 F.3d 62","y":2017,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/847/62/","by":{"1":"43"}},{"t":"case","label":"Taylor v. United States","cite":"564 U.S. 1029","y":2011,"url":"https://supreme.justia.com/cases/federal/us/564/1029/","sc":1,"by":{"1":"5"}},{"t":"case","label":"United States v. Aparicio-Soria","cite":"740 F.3d 152","y":2014,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/740/152/","by":{"1":"43"}},{"t":"case","label":"United States v. Bailey","cite":"819 F.3d 92","y":2016,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/819/92/","by":{"1":"15"}},{"t":"case","label":"United States v. Castillo-Rivera","cite":"853 F.3d 218","y":2017,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/853/218/","by":{"1":"44"}},{"t":"case","label":"United States v. Castleman","cite":"572 U.S. 157","y":2014,"id":"2013/12-1371","sc":1,"sum":"The Court held that a Tennessee man's conviction of domestic violence under state law also prevented him from legally possessing firearms under federal law.","sumSrc":"Oyez","by":{"1":"14","2":"19"}},{"t":"case","label":"United States v. Delis","cite":"558 F.3d 177","y":2009,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/558/177/","by":{"1":"38"}},{"t":"case","label":"United States v. Diamond","cite":"463 F. App’x 608","y":2011,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/463/608/","by":{"1":"38"}},{"t":"case","label":"United States v. Dupree","cite":"544 F.2d 1050","y":1976,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/544/1050/","by":{"1":"37"}},{"t":"case","label":"United States v. Gonzalez","cite":"520 U.S. 1","y":1997,"id":"1996/95-1605","sc":1,"sum":"In a 7-to-2 decision delivered by Justice Sandra Day O'Connor, the Court announced \"[t]he plain language of (the law) forbids a district court to direct that a term of imprisonment under the statute run concurrently with any other term of imprisonment, whether state or federal.\".","sumSrc":"Oyez","by":{"1":"2"}},{"t":"case","label":"United States v. Hathaway","cite":"318 F.3d 1001","y":2003,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/318/1001/","by":{"1":"37"}},{"t":"case","label":"United States v. Havis","cite":"907 F.3d 439","y":2018,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/907/439/","by":{"1":"43"}},{"t":"case","label":"United States v. Hite","cite":"769 F.3d 1154","y":2014,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/769/1154/","by":{"1":"11"}},{"t":"case","label":"United States v. Holloway","cite":"309 F.3d 649","y":2002,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/309/649/","by":{"1":"45"}},{"t":"case","label":"United States v. Loera","cite":"923 F.2d 725","y":1991,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/923/725/","by":{"1":"38"}},{"t":"case","label":"United States v. McFadden","cite":"739 F.2d 149","y":1984,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/739/149/","by":{"1":"12","2":"5"}},{"t":"case","label":"United States v. Middleton","cite":"883 F.3d 485","y":2018,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/883/485/","by":{"1":"23"}},{"t":"case","label":"United States v. Ron Pair Enters., Inc.","cite":"489 U.S. 235","y":1989,"id":"1988/87-1043","sc":1,"sum":"Section 506(b) entitles a creditor to receive postpetition interest on a nonconsensual oversecured claim allowed in a bankruptcy proceeding.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"29"}},{"t":"case","label":"United States v. Santos","cite":"553 U.S. 507","y":2008,"id":"2007/06-1005","sc":1,"sum":"Splitting 5 to 4, the Court affirmed the Seventh Circuit, answering that \"proceeds\" refers to \"net income\" or profits and not to \"gross income.\" Because the statute nowhere defines the term \"proceeds\", the plurality applied the so-called rule of lenity which requires such ambiguous statutes to be interpreted in favor of defendants.","sumSrc":"Oyez","by":{"1":"48"}},{"t":"case","label":"United States v. Smith","cite":"1991 WL 36269","y":1991,"court":"7th Cir.","by":{"1":"27"}},{"t":"case","label":"United States v. Titties","cite":"852 F.3d 1257","y":2017,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/852/1257/","by":{"1":"43"}},{"t":"case","label":"United States v. Williams","cite":"531 F. App’x 270","y":2013,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/531/270/","by":{"1":"45"}},{"t":"case","label":"United States v. Wiltberger","cite":"18 U.S. 76","y":1820,"id":"scdb/1820-003","sc":1,"sum":"The United States v. Wiltberger.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"48"}},{"t":"case","label":"Welch v. United States","cite":"136 S. Ct. 1257","y":2016,"id":"2015/15-6418","sc":1,"op":1,"sum":"The Court held that the rule the Supreme Court announced in Johnson v. United States regarding what constitutes a violent offense for the purposes of sentencing under the Armed Career Criminal Act applies retroactively.","sumSrc":"Oyez","by":{"1":"5, 6"}},{"t":"case","label":"Whyte v. Lynch","cite":"807 F.3d 463","y":2015,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/807/463/","by":{"1":"39"}},{"t":"usc","label":"18 U.S.C. § 921","url":"https://www.law.cornell.edu/uscode/text/18/921","subs":["(a)"],"by":{"1":"41, 42"}},{"t":"usc","label":"18 U.S.C. § 922","url":"https://www.law.cornell.edu/uscode/text/18/922","subs":["(g)"],"by":{"1":"14"}},{"t":"law","label":"Pub. L. No. 98-473","url":"https://www.govinfo.gov/link/statute/98/2185","by":{"1":"35, 17","2":"18"}},{"t":"law","label":"Pub. L. No. 99-570","url":"https://www.govinfo.gov/link/statute/100/3207","by":{"1":"36"}},{"t":"case","label":"Brnovich v. Democratic Nat’l Comm.","cite":"141 S. Ct. 2321","y":2021,"id":"2020/19-1257","sc":1,"sum":"Arizona’s challenged voting regulations governing precinct-based election-day voting (rejecting ballots cast in the wrong precinct) and early mail-in voting (making it a crime for anyone other than an authorized proxy to possess the early ballot of another voter) do not violate §2 of the Voting Rights Act of 1965; Arizona House Bill 2023 (enacting the early mail-in voting regulations) was not enacted with a racially discriminatory purpose.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"9"}},{"t":"case","label":"Griffin v. United States","cite":"336 U.S. 704","y":1949,"id":"scdb/1948-069","sc":1,"sum":"The cause is remanded to the Court of Appeals with instructions to decide, in the first instance, what rule of evidence should prevail in the District of Columbia.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"14"}},{"t":"case","label":"Helvering v. Gregory","cite":"69 F.2d 809","y":1934,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/69/809/","by":{"2":"9"}},{"t":"case","label":"Horn & Hardart Co. v. National R.R. Passenger Corp.","cite":"793 F.2d 356","y":1986,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/793/356/","by":{"2":"13"}},{"t":"case","label":"Tafflin v. Levitt","cite":"493 U.S. 455","y":1990,"id":"1989/88-1650","sc":1,"sum":"State courts have concurrent jurisdiction over civil RICO claims. The presumption in favor of such jurisdiction has not been rebutted by any of the factors identified in Gulf Offshore Co. v. Mobil Oil Corp., 453 U. S. 473, 478.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"8"}},{"t":"case","label":"United States v. Muratovic","cite":"719 F.3d 809","y":2013,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/719/809/","by":{"2":"3"}},{"t":"case","label":"United States v. Williams","cite":"531 Fed. Appx. 270","y":2013,"court":"3d Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./531/270/","op":1,"by":{"2":"7, 8"}},{"t":"usc","label":"18 U.S.C. § 25","url":"https://www.law.cornell.edu/uscode/text/18/25","by":{"2":"21"}},{"t":"usc","label":"18 U.S.C. § 111","url":"https://www.law.cornell.edu/uscode/text/18/111","subs":["(b)"],"by":{"2":"11"}},{"t":"usc","label":"18 U.S.C. § 931","url":"https://www.law.cornell.edu/uscode/text/18/931","by":{"2":"21"}},{"t":"usc","label":"18 U.S.C. § 1113","url":"https://www.law.cornell.edu/uscode/text/18/1113","by":{"2":"11"}},{"t":"usc","label":"18 U.S.C. § 1201","url":"https://www.law.cornell.edu/uscode/text/18/1201","subs":["(a)"],"by":{"2":"17"}},{"t":"usc","label":"18 U.S.C. § 1591","url":"https://www.law.cornell.edu/uscode/text/18/1591","subs":["(a)"],"by":{"2":"17"}},{"t":"usc","label":"18 U.S.C. § 2339A","url":"https://www.law.cornell.edu/uscode/text/18/2339A","by":{"2":"17"}},{"t":"usc","label":"18 U.S.C. § 2339B","url":"https://www.law.cornell.edu/uscode/text/18/2339B","by":{"2":"17"}},{"t":"usc","label":"18 U.S.C. § 3663A","url":"https://www.law.cornell.edu/uscode/text/18/3663A","by":{"2":"21"}}]};